"""Small administration view for Feishu user policy and audit access."""

FEISHU_USERS_PAGE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><script src="https://cdn.tailwindcss.com"></script><title>飞书用户管理</title></head><body class="min-h-screen bg-slate-950 p-7 text-slate-100"><a href="/admin" class="text-sm text-sky-300">← 返回管理平台</a><div class="mt-5 flex items-end justify-between"><div><h1 class="text-2xl font-bold">飞书用户管理</h1><p class="mt-2 text-sm text-slate-400">最终工具 = 飞书平台 Key 基础工具 + 用户角色工具 + 用户额外工具。</p></div><button onclick="load()" class="rounded bg-sky-500 px-3 py-2 text-sm">刷新</button></div><div class="mt-6 overflow-x-auto rounded-xl border border-slate-800"><table class="w-full text-left text-sm"><thead class="bg-slate-900 text-slate-400"><tr><th class="p-4">飞书用户</th><th>角色</th><th>额外工具</th><th>最终工具</th><th>会话</th><th>状态</th><th>操作</th></tr></thead><tbody id="rows"></tbody></table></div><dialog id="edit" class="w-full max-w-2xl rounded-xl border border-slate-700 bg-slate-900 p-6 text-slate-100"><form method="dialog"><div class="flex justify-between"><h2 id="name" class="text-lg font-bold"></h2><button>×</button></div><p class="mt-1 text-xs text-slate-400" id="openid"></p><h3 class="mt-5 font-semibold">额外绑定角色</h3><div id="roles" class="mt-2 grid gap-2 sm:grid-cols-2"></div><h3 class="mt-5 font-semibold">额外工具</h3><div id="tools" class="mt-2 grid gap-2 sm:grid-cols-2"></div><label class="mt-5 flex gap-2"><input id="active" type="checkbox"> 启用该飞书用户</label><div class="mt-6 flex justify-end gap-3"><button>取消</button><button type="button" onclick="save()" class="rounded bg-emerald-400 px-4 py-2 font-semibold text-slate-950">保存</button></div></form></dialog><script>let users=[],roles=[],tools=[],selected=null;const e=s=>document.querySelector(s);const esc=s=>String(s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));async function api(u,o={}){const r=await fetch('/admin'+u,{headers:{'Content-Type':'application/json'},...o});if(!r.ok)throw Error((await r.json()).detail||'请求失败');return r.status===204?null:r.json()}function chips(items,field='name'){return items.length?items.map(x=>`<span class="mr-1 inline-block rounded bg-slate-800 px-2 py-1 text-xs" title="${esc(x[field])}">${esc(x[field])}</span>`).join(''):'—'}function render(){e('#rows').innerHTML=users.map(u=>`<tr class="border-t border-slate-800"><td class="p-4"><div class="font-semibold">${esc(u.display_name)}</div><div class="mt-1 font-mono text-xs text-slate-500">${esc(u.open_id)}</div></td><td>${chips(u.role_ids.map(id=>roles.find(x=>x.id===id)).filter(Boolean))}</td><td>${chips(u.extra_tool_ids.map(id=>tools.find(x=>x.id===id)).filter(Boolean))}</td><td>${chips(u.effective_tools)}</td><td><button onclick="sessions('${u.id}')" class="text-sky-300">${u.session_count} 个会话</button></td><td><span class="rounded px-2 py-1 text-xs ${u.is_active?'bg-emerald-500/20 text-emerald-300':'bg-slate-700'}">${u.is_active?'启用':'禁用'}</span></td><td><button onclick="openEdit('${u.id}')" class="text-sky-300">编辑</button></td></tr>`).join('')||'<tr><td colspan="7" class="p-10 text-center text-slate-500">尚未收到飞书用户消息</td></tr>'}async function load(){[users,roles,tools]=await Promise.all([api('/feishu-users'),api('/roles'),api('/mcp-tools')]);render()}function openEdit(id){selected=users.find(u=>u.id===id);e('#name').textContent=selected.display_name;e('#openid').textContent=selected.open_id;e('#active').checked=selected.is_active;e('#roles').innerHTML=roles.map(x=>`<label><input type="checkbox" value="${x.id}" ${selected.role_ids.includes(x.id)?'checked':''}> ${esc(x.name)}</label>`).join('');e('#tools').innerHTML=tools.map(x=>`<label><input type="checkbox" value="${x.id}" ${selected.extra_tool_ids.includes(x.id)?'checked':''}> ${esc(x.name)}</label>`).join('');e('#edit').showModal()}async function save(){const ids=s=>[...document.querySelectorAll(s+':checked')].map(x=>x.value);await api('/feishu-users/'+selected.id,{method:'PUT',body:JSON.stringify({role_ids:ids('#roles input'),extra_tool_ids:ids('#tools input'),is_active:e('#active').checked})});e('#edit').close();load()}async function sessions(id){const ss=await api('/feishu-users/'+id+'/sessions');alert(ss.map(x=>`${x.is_archived?'[已隐藏] ':''}${x.title}\n${x.last_used_at}`).join('\n\n')||'暂无会话')}load().catch(x=>alert(x.message));</script></body></html>'''
